const SonarStrategy: React.FC<SonarStrategyProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 12,
  headerLine1 = "How To Find",
  headerLine2Start = "Winning",
  headerLine2Middle = "Content",
  headerLine2End = "Strategy",
  profileName = "kallaway",
  followerCount = "437k followers",
  buttonText = "Following",
  avatarUrl = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&auto=format&fit=crop&q=80",
  radarColor = "#22c55e",
  accentColor = "#dc2626",
  showPaperTexture = true,
  paperOpacity = 0.18,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout sizing relative to portrait 1080x1920 canvas
  const centerX = width / 2;
  const centerY = height * 0.54;
  const cardSize = width * 0.58;
  const avatarSize = cardSize * 0.44;
  const radarRadiusMax = width * 0.45;

  // Animation Springs & Interpolations

  // 1. Central Card Entrance (0 - 40 frames)
  const cardEntranceSpring = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.8 },
  });
  const cardScale = interpolate(cardEntranceSpring, [0, 1], [0, 1]);

  // Subtle continuous floating/bobbing idle effect for high-end look
  const floatY = Math.sin(frame * 0.06) * 6;

  // 2. Concentric Rings Sequential Expanding Entrance
  const ring1Scale = spring({
    frame: frame - 16,
    fps,
    config: { damping: 15, mass: 1 },
  });
  const ring2Scale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 15, mass: 1 },
  });
  const ring3Scale = spring({
    frame: frame - 4,
    fps,
    config: { damping: 15, mass: 1 },
  });

  // Slow harmonic radar ring pulse
  const ringPulse = Math.sin(frame * 0.05) * 0.015 + 1.0;

  // 3. Continuous Radar Sweep Rotation
  const radarRotation = (frame * 2.2) % 360;
  const sweepOpacity = interpolate(frame, [20, 50], [0, 0.65], {
    extrapolateRight: "clamp",
  });

  // 4. Header Animated Entrance
  const titleSpring = spring({
    frame: frame - 8,
    fps,
    config: { damping: 12 },
  });
  const titleY = interpolate(titleSpring, [0, 1], [-40, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);

  const barSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14 },
  });
  const barWidthPercent = interpolate(barSpring, [0, 1], [0, 90]);
  const barOpacity = interpolate(barSpring, [0, 1], [0, 1]);

  const barTextSpring = spring({
    frame: frame - 22,
    fps,
    config: { damping: 12 },
  });
  const barTextScale = interpolate(barTextSpring, [0, 1], [0.85, 1]);
  const barTextOpacity = interpolate(barTextSpring, [0, 1], [0, 1]);

  // 5. Profile Details Entrance inside Card
  const avatarSpring = spring({
    frame: frame - 24,
    fps,
    config: { damping: 12 },
  });
  const avatarScale = interpolate(avatarSpring, [0, 1], [0, 1]);

  const nameSpring = spring({
    frame: frame - 30,
    fps,
    config: { damping: 12 },
  });
  const nameY = interpolate(nameSpring, [0, 1], [15, 0]);
  const nameOpacity = interpolate(nameSpring, [0, 1], [0, 1]);

  const followersSpring = spring({
    frame: frame - 36,
    fps,
    config: { damping: 12 },
  });
  const followersOpacity = interpolate(followersSpring, [0, 1], [0, 1]);

  const buttonSpring = spring({
    frame: frame - 42,
    fps,
    config: { damping: 12 },
  });
  const buttonScale = interpolate(buttonSpring, [0, 1], [0, 1]);

  // Grid background styling (matches image textured feel)
  const bgGridStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundImage: `
      linear-gradient(rgba(255, 255, 255, 0.015) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255, 255, 255, 0.015) 1px, transparent 1px)
    `,
    backgroundSize: "40px 40px",
    backgroundPosition: "center",
  };

  // Profile Card internal grid styling
  const cardGridStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundImage: `
      linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px)
    `,
    backgroundSize: "24px 24px",
    backgroundPosition: "center",
    borderRadius: "50%",
    pointerEvents: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background Grid Pattern */}
      <div style={bgGridStyle} />

      {/* Top Header Section */}
      <div
        style={{
          position: "absolute",
          top: "13%",
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        <div
          style={{
            color: "#ffffff",
            fontSize: 44,
            fontWeight: 800,
            letterSpacing: "-0.5px",
            marginBottom: 16,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {headerLine1}
        </div>

        {/* Dynamic Highlight Bar */}
        <div
          style={{
            width: `${barWidthPercent}%`,
            backgroundColor: accentColor,
            padding: "16px 36px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 10px 40px rgba(220, 38, 38, 0.3)",
            opacity: barOpacity,
            overflow: "hidden",
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          <div
            style={{
              color: "#ffffff",
              fontSize: 48,
              fontWeight: 900,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: `scale(${barTextScale})`,
              opacity: barTextOpacity,
              letterSpacing: "-0.5px",
              transition: "none",
            }}
          >
            <span style={{ marginRight: 12 }}>{headerLine2Start}</span>
            <span
              style={{
                fontFamily: playfairFamily,
                fontStyle: "italic",
                fontWeight: "normal",
                marginRight: 12,
              }}
            >
              {headerLine2Middle}
            </span>
            <span>{headerLine2End}</span>
          </div>
        </div>
      </div>

      {/* Sonar Scan Radar Effect */}
      <div
        style={{
          position: "absolute",
          width: radarRadiusMax * 2.2,
          height: radarRadiusMax * 2.2,
          borderRadius: "50%",
          left: centerX - radarRadiusMax * 1.1,
          top: centerY - radarRadiusMax * 1.1,
          background: `radial-gradient(circle, ${radarColor}15 0%, transparent 70%)`,
          pointerEvents: "none",
          zIndex: 0,
          transform: `scale(${interpolate(frame, [0, 60], [0.6, 1], { extrapolateRight: "clamp" })})`,
          opacity: interpolate(frame, [0, 60], [0, 1], { extrapolateRight: "clamp" }),
          transition: "none",
        }}
      />

      {/* Outer Concentric Sonar Rings */}
      {[
        { scale: ring1Scale, radius: radarRadiusMax },
        { scale: ring2Scale, radius: radarRadiusMax * 0.8 },
        { scale: ring3Scale, radius: radarRadiusMax * 0.6 },
      ].map((ring, index) => {
        const ringScaleCalculated = ring.scale * ringPulse;
        return (
          <div
            key={index}
            style={{
              position: "absolute",
              width: ring.radius * 2,
              height: ring.radius * 2,
              borderRadius: "50%",
              border: "1.5px solid rgba(255, 255, 255, 0.12)",
              left: centerX - ring.radius,
              top: centerY - ring.radius,
              transform: `scale(${ringScaleCalculated})`,
              opacity: interpolate(ring.scale, [0, 1], [0, 1]),
              pointerEvents: "none",
              transition: "none",
              zIndex: 1,
            }}
          />
        );
      })}

      {/* Rotating Radar Sweep Cone */}
      <div
        style={{
          position: "absolute",
          width: radarRadiusMax * 2,
          height: radarRadiusMax * 2,
          borderRadius: "50%",
          left: centerX - radarRadiusMax,
          top: centerY - radarRadiusMax,
          background: `conic-gradient(from 0deg, ${radarColor}70 0deg, ${radarColor}00 75deg, transparent 75deg)`,
          transform: `rotate(${radarRotation}deg)`,
          opacity: sweepOpacity,
          pointerEvents: "none",
          zIndex: 1,
          transition: "none",
        }}
      />

      {/* Central Profile Card Component */}
      <div
        style={{
          position: "absolute",
          width: cardSize,
          height: cardSize,
          borderRadius: "50%",
          backgroundColor: "rgba(28, 28, 30, 0.82)",
          border: "1.5px solid rgba(255, 255, 255, 0.16)",
          boxShadow: "0 25px 60px rgba(0, 0, 0, 0.6)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          left: centerX - cardSize / 2,
          top: centerY - cardSize / 2,
          overflow: "hidden",
          transform: `scale(${cardScale}) translateY(${floatY}px)`,
          transition: "none",
          zIndex: 2,
        }}
      >
        {/* Card Sub-Grid Background Layer */}
        <div style={cardGridStyle} />

        {/* Content Wrapper */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            width: "100%",
            zIndex: 3,
          }}
        >
          {/* Circular Avatar */}
          <div
            style={{
              width: avatarSize,
              height: avatarSize,
              borderRadius: "50%",
              border: "3px solid rgba(255, 255, 255, 0.18)",
              overflow: "hidden",
              boxShadow: "0 10px 25px rgba(0, 0, 0, 0.5)",
              transform: `scale(${avatarScale})`,
              transition: "none",
              backgroundColor: "#111",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Img
              src={avatarUrl}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
          </div>

          {/* Name & Verification Badge */}
          <div
            style={{
              marginTop: 22,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: nameOpacity,
              transform: `translateY(${nameY}px)`,
              transition: "none",
            }}
          >
            <span
              style={{
                color: "#ffffff",
                fontSize: 36,
                fontWeight: 700,
                letterSpacing: "-0.5px",
              }}
            >
              {profileName}
            </span>
            <VerifiedBadge />
          </div>

          {/* Follower Count */}
          <div
            style={{
              color: "rgba(255, 255, 255, 0.65)",
              fontSize: 22,
              fontWeight: 500,
              marginTop: 6,
              opacity: followersOpacity,
              transition: "none",
            }}
          >
            {followerCount}
          </div>

          {/* Following Button */}
          <div
            style={{
              marginTop: 18,
              backgroundColor: "#000000",
              border: "1.5px solid rgba(255, 255, 255, 0.25)",
              borderRadius: "999px",
              padding: "10px 32px",
              color: "#ffffff",
              fontSize: 18,
              fontWeight: 600,
              letterSpacing: "0.2px",
              transform: `scale(${buttonScale})`,
              transition: "none",
              boxShadow: "0 4px 15px rgba(0,0,0,0.4)",
            }}
          >
            {buttonText}
          </div>
        </div>
      </div>

      {/* Tactile VOX-Style Paper Texture Overlay */}
      {showPaperTexture && <PaperOverlay opacity={paperOpacity} />}
    </AbsoluteFill>
  );
};

export default SonarStrategy;